from __future__ import annotations

from html import escape

from fastapi import HTTPException, Request
from fastapi.responses import HTMLResponse

from .branding import PRODUCT_NAME


_EFFECT_SYSTEM_CREATOR_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow">
<title>Aura Effect/System Creator — __PRODUCT__</title>
<style>
:root{--bg:#05040a;--panel:#11101b;--line:#ffffff1d;--gold:#f2c86f;--violet:#a36cff;--cyan:#5ce8ff;--muted:#bdb7ca;--good:#7de2aa;--bad:#ff95aa;--warn:#ffd27a}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 8% 0,#42155e,transparent 31%),radial-gradient(circle at 92% 0,#123d58,transparent 27%),var(--bg);color:#fff;font-family:Inter,system-ui,sans-serif;min-height:100vh}a{color:inherit;text-decoration:none}button,input,textarea{font:inherit}.wrap{width:min(1450px,calc(100% - 26px));margin:auto;padding:28px 0 80px}.top,.actions,.toolbar,.nodeTop,.statusRow{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.top{justify-content:space-between}.eyebrow{color:var(--gold);font-size:.69rem;letter-spacing:.15em;text-transform:uppercase;font-weight:950}h1{font-size:clamp(2.7rem,7vw,5.4rem);letter-spacing:-.055em;line-height:.93;margin:.14em 0 .18em}.lead,.muted,small{color:var(--muted);line-height:1.55}.btn,input,textarea{border:1px solid var(--line);border-radius:11px;background:#ffffff08;color:#fff;padding:10px 12px}.btn{font-weight:850;cursor:pointer}.btn.primary{border:0;background:linear-gradient(110deg,#fff0ae,var(--gold),var(--violet));color:#160b1d}.btn.danger{border-color:#ff95aa55;color:#ffd2da}.btn:disabled{opacity:.4;cursor:not-allowed}.layout{display:grid;grid-template-columns:.82fr 1.18fr;gap:13px;margin-top:20px}.panel{border:1px solid var(--line);border-radius:20px;padding:16px;background:linear-gradient(145deg,#15101fea,#090711ef);min-width:0}.panel h2{margin:4px 0 8px}.stack{display:grid;gap:9px}.row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.prompt{min-height:125px;resize:vertical}.notice{display:none;padding:11px 13px;border:1px solid var(--line);border-radius:12px;margin:10px 0;background:#ffffff07}.notice.show{display:block}.notice.good{color:var(--good);border-color:#7de2aa55}.notice.error{color:#ffd5dd;border-color:#ff95aa55}.notice.warn{color:var(--warn);border-color:#ffd27a55}.nodes{display:grid;gap:9px;margin-top:12px}.node{border:1px solid var(--line);border-radius:15px;padding:12px;background:#080912}.nodeTop{justify-content:space-between}.nodeTitle{font-weight:900}.nodeId{font:600 .67rem ui-monospace,SFMono-Regular,Menlo,monospace;color:#8f93a8;word-break:break-all}.params{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-top:10px}.param{display:grid;gap:4px}.param label{font-size:.7rem;color:var(--muted)}.param input{width:100%;padding:8px}.mix{display:grid;grid-template-columns:auto 1fr auto;gap:7px;align-items:center;margin-top:9px}.mix input{padding:0}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:5px 8px;font-size:.68rem}.pill.good{color:var(--good)}.pill.warn{color:var(--warn)}.preview{font:600 .7rem ui-monospace,SFMono-Regular,Menlo,monospace;white-space:pre-wrap;word-break:break-word;max-height:260px;overflow:auto;background:#05060b;border:1px solid var(--line);border-radius:12px;padding:10px}.saved{display:grid;gap:7px;margin-top:10px}.savedRow{display:flex;justify-content:space-between;gap:10px;align-items:center;border:1px solid var(--line);border-radius:12px;padding:9px;background:#ffffff05}.empty{border:1px dashed #ffffff2a;border-radius:14px;padding:20px;color:var(--muted);text-align:center}@media(max-width:950px){.layout{grid-template-columns:1fr}}@media(max-width:620px){.row,.params{grid-template-columns:1fr}.top{align-items:flex-start}.top .actions{width:100%}}
</style></head><body><main class="wrap">
<header class="top"><div><div class="eyebrow">Aura AI · Editable Effect Systems · __PLAN__ plan</div><h1>Describe it. Edit it. Preview it.</h1><p class="lead">Aura turns supported music-effect instructions into a bounded executable node chain. Every node remains editable. Preview creates a fingerprint token for the exact current graph; Apply re-checks ownership and refuses a changed graph until it is previewed again.</p></div><div class="actions"><a class="btn" href="/creative/effects-library">Effects Library</a><a class="btn" href="/creative-house">Creative House</a><a class="btn" href="/dashboard">Dashboard</a></div></header>
<div id="notice" class="notice" role="status" aria-live="polite"></div>
<section class="layout"><div class="stack">
<div class="panel"><div class="eyebrow">1 · Aura prompt</div><h2>Compose a starting chain</h2><textarea id="prompt" class="prompt" placeholder="Example: High pass at 120 Hz, add compression 4:1, reverb 25%, then widen the stereo image 65%."></textarea><div class="row"><input id="systemId" placeholder="System ID, e.g. aura.vocal.space"><input id="systemName" placeholder="System name"></div><div class="actions" style="margin-top:9px"><button id="compose" class="btn primary">Compose with Aura</button><button id="clear" class="btn">Clear editor</button></div><p class="muted">Only allowlisted executable music effects are accepted. Unsupported prompts fail closed; no shell, process or device commands can be generated.</p></div>
<div class="panel"><div class="eyebrow">2 · Project target</div><h2>Save, preview and apply</h2><div class="row"><input id="project" placeholder="Project ID"><input id="track" placeholder="Track ID"></div><div class="row"><input id="version" type="number" min="1" value="1" aria-label="System version"><input id="description" placeholder="Description"></div><div class="actions" style="margin-top:9px"><button id="loadSaved" class="btn">Load saved systems</button><button id="save" class="btn">Save version</button><button id="preview" class="btn">Preview current graph</button><button id="apply" class="btn primary" disabled>Apply previewed graph</button><button id="undo" class="btn" disabled>Undo last apply</button></div><div class="statusRow" style="margin-top:10px"><span id="previewState" class="pill warn">Preview required</span><span id="ownershipState" class="pill">Ownership not checked</span></div><p class="muted">Saving never grants effect ownership. Apply is enabled only for the exact previewed fingerprint and the server re-checks entitlements immediately before mutation.</p></div>
<div class="panel"><div class="eyebrow">Saved project systems</div><div id="saved" class="saved"><div class="empty">Choose a project and load saved systems.</div></div></div>
</div><div class="stack">
<div class="panel"><div class="eyebrow">3 · Editable typed nodes</div><div class="toolbar"><h2 style="flex:1">Current chain</h2><button id="addNode" class="btn">Add effect by ID</button></div><div id="nodes" class="nodes"><div class="empty">Compose a supported prompt or add an effect node.</div></div></div>
<div class="panel"><div class="eyebrow">Compiled preview evidence</div><h2>Renderer plan</h2><div id="compiled" class="preview">Nothing compiled yet.</div></div>
</div></section></main>
<script>
(()=>{'use strict';
const API='/command-center/api/universal-library/effect-systems';const q=id=>document.getElementById(id);let system=null,promptFingerprint='',previewToken='',lastRevision='',canApply=false;
function notify(message,kind=''){const n=q('notice');n.textContent=String(message||'');n.className='notice show '+kind;clearTimeout(window.__auraFxNotice);window.__auraFxNotice=setTimeout(()=>n.className='notice',6500)}
async function api(path,opt={}){const res=await fetch(API+path,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...opt});let body={};try{body=await res.json()}catch(_e){}if(!res.ok)throw new Error(body.detail||`Request failed (${res.status})`);return body}
function invalidated(){previewToken='';canApply=false;q('apply').disabled=true;q('previewState').textContent='Preview required';q('previewState').className='pill warn';q('ownershipState').textContent='Ownership not checked';q('ownershipState').className='pill'}
function value(v){const n=Number(v);return Number.isFinite(n)?n:v}
function syncMeta(){if(!system)return;system.id=q('systemId').value.trim();system.name=q('systemName').value.trim();system.description=q('description').value.trim();system.version=Math.max(1,Number(q('version').value)||1)}
function body(){syncMeta();if(!system)throw new Error('Compose or load an effect system first.');return {system,source_prompt_fingerprint:promptFingerprint}}
function nodeLabel(node){return node.catalogue_item_id||'Effect node'}
function renderNodes(){const root=q('nodes');root.replaceChildren();if(!system||!Array.isArray(system.nodes)||!system.nodes.length){const e=document.createElement('div');e.className='empty';e.textContent='Compose a supported prompt or add an effect node.';root.appendChild(e);return}system.nodes.forEach((node,index)=>{const card=document.createElement('article');card.className='node';const top=document.createElement('div');top.className='nodeTop';const title=document.createElement('div');title.className='nodeTitle';title.textContent=`${index+1}. ${nodeLabel(node)}`;const controls=document.createElement('div');controls.className='actions';[['↑',-1],['↓',1]].forEach(([label,delta])=>{const b=document.createElement('button');b.className='btn';b.type='button';b.textContent=label;b.disabled=(delta<0&&index===0)||(delta>0&&index===system.nodes.length-1);b.onclick=()=>{const target=index+delta;[system.nodes[index],system.nodes[target]]=[system.nodes[target],system.nodes[index]];invalidated();renderNodes()};controls.appendChild(b)});const remove=document.createElement('button');remove.className='btn danger';remove.type='button';remove.textContent='Remove';remove.onclick=()=>{system.nodes.splice(index,1);invalidated();renderNodes()};controls.appendChild(remove);top.append(title,controls);card.appendChild(top);const id=document.createElement('div');id.className='nodeId';id.textContent=node.id;card.appendChild(id);
const effect=document.createElement('div');effect.className='param';const effectLabel=document.createElement('label');effectLabel.textContent='Catalogue effect ID';const effectInput=document.createElement('input');effectInput.value=node.catalogue_item_id||'';effectInput.oninput=()=>{node.catalogue_item_id=effectInput.value.trim();invalidated()};effect.append(effectLabel,effectInput);card.appendChild(effect);
const params=document.createElement('div');params.className='params';Object.entries(node.parameters||{}).forEach(([key,current])=>{const wrap=document.createElement('div');wrap.className='param';const label=document.createElement('label');label.textContent=key;const input=document.createElement('input');input.value=String(current);input.oninput=()=>{node.parameters[key]=value(input.value);invalidated()};wrap.append(label,input);params.appendChild(wrap)});card.appendChild(params);
const mix=document.createElement('div');mix.className='mix';const enabled=document.createElement('input');enabled.type='checkbox';enabled.checked=node.enabled!==false;enabled.onchange=()=>{node.enabled=enabled.checked;invalidated()};const range=document.createElement('input');range.type='range';range.min='0';range.max='1';range.step='.01';range.value=String(node.mix??1);const out=document.createElement('span');out.textContent=`${Math.round(Number(range.value)*100)}%`;range.oninput=()=>{node.mix=Number(range.value);out.textContent=`${Math.round(node.mix*100)}%`;invalidated()};mix.append(enabled,range,out);card.appendChild(mix);root.appendChild(card)})}
function setSystem(next,fingerprint=''){system=JSON.parse(JSON.stringify(next));promptFingerprint=fingerprint||'';q('systemId').value=system.id||'';q('systemName').value=system.name||'';q('description').value=system.description||'';q('version').value=String(system.version||1);invalidated();renderNodes();q('compiled').textContent='Graph loaded. Preview before apply.'}
q('compose').onclick=async()=>{try{const payload={prompt:q('prompt').value.trim(),system_id:q('systemId').value.trim()||null,name:q('systemName').value.trim()||null};const data=await api('/compose',{method:'POST',body:JSON.stringify(payload)});setSystem(data.system,data.prompt_fingerprint||'');canApply=Boolean(data.can_apply);q('ownershipState').textContent=canApply?'Effects owned/included':'Missing effect ownership';q('ownershipState').className='pill '+(canApply?'good':'warn');q('compiled').textContent=JSON.stringify({fingerprint:data.fingerprint,filter_chain:data.ffmpeg_filter_chain,missing:data.missing_entitlement_effect_ids||[]},null,2);notify('Aura composed an editable executable chain. Review the nodes, then preview it.','good')}catch(e){notify(e.message,'error')}};
q('clear').onclick=()=>{system=null;promptFingerprint='';lastRevision='';q('prompt').value='';q('systemId').value='';q('systemName').value='';q('description').value='';q('version').value='1';q('compiled').textContent='Nothing compiled yet.';q('undo').disabled=true;invalidated();renderNodes()};
q('addNode').onclick=()=>{if(!system){system={id:q('systemId').value.trim()||'aura.custom.chain',name:q('systemName').value.trim()||'Custom Effect Chain',description:q('description').value.trim(),version:Math.max(1,Number(q('version').value)||1),nodes:[]}}const effect=window.prompt('Catalogue effect ID, e.g. music.fx.reverb');if(!effect)return;system.nodes.push({id:`fx${String(system.nodes.length+1).padStart(2,'0')}`,catalogue_item_id:effect.trim(),parameters:{},enabled:true,mix:1});invalidated();renderNodes()};
q('save').onclick=async()=>{try{const project=q('project').value.trim();if(!project)throw new Error('Project ID is required.');const data=await api(`/projects/${encodeURIComponent(project)}/save`,{method:'POST',body:JSON.stringify(body())});notify(`Saved ${data.system?.name||system.name} v${data.system?.version||system.version}.`,'good');await loadSaved()}catch(e){notify(e.message,'error')}};
async function loadSaved(){try{const project=q('project').value.trim();if(!project)throw new Error('Project ID is required.');const data=await api(`/projects/${encodeURIComponent(project)}`);const root=q('saved');root.replaceChildren();if(!data.items?.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='No saved effect systems in this project yet.';root.appendChild(empty);return}data.items.forEach(item=>{const row=document.createElement('div');row.className='savedRow';const text=document.createElement('div');const strong=document.createElement('strong');strong.textContent=`${item.name} · v${item.version}`;const small=document.createElement('small');small.textContent=`${item.id} · ${item.node_count} nodes`;text.append(strong,document.createElement('br'),small);const load=document.createElement('button');load.className='btn';load.textContent='Load';load.onclick=async()=>{try{const loaded=await api(`/projects/${encodeURIComponent(project)}/${encodeURIComponent(item.id)}`);setSystem(loaded.system,loaded.source_prompt_fingerprint||'');q('compiled').textContent=JSON.stringify({fingerprint:loaded.fingerprint,filter_chain:loaded.ffmpeg_filter_chain},null,2);notify('Saved system loaded. Preview it before apply.','good')}catch(e){notify(e.message,'error')}};row.append(text,load);root.appendChild(row)})}catch(e){notify(e.message,'error')}}q('loadSaved').onclick=loadSaved;
q('preview').onclick=async()=>{try{const project=q('project').value.trim(),track=q('track').value.trim();if(!project||!track)throw new Error('Project ID and Track ID are required.');const data=await api(`/projects/${encodeURIComponent(project)}/tracks/${encodeURIComponent(track)}/preview`,{method:'POST',body:JSON.stringify(body())});previewToken=data.preview_token||'';canApply=Boolean(data.can_apply);q('apply').disabled=!previewToken||!canApply;q('previewState').textContent=previewToken?'Current graph previewed':'Preview required';q('previewState').className='pill '+(previewToken?'good':'warn');q('ownershipState').textContent=canApply?'Effects owned/included':'Missing effect ownership';q('ownershipState').className='pill '+(canApply?'good':'warn');q('compiled').textContent=JSON.stringify({fingerprint:data.fingerprint,filter_chain:data.ffmpeg_filter_chain,effects:data.effects,missing:data.missing_entitlement_effect_ids||[]},null,2);notify(canApply?'Preview ready. Apply is available for this exact graph.':'Preview ready, but one or more effects are not owned.','good')}catch(e){invalidated();notify(e.message,'error')}};
q('apply').onclick=async()=>{try{if(!previewToken)throw new Error('Preview the current graph before apply.');const project=q('project').value.trim(),track=q('track').value.trim();const payload={...body(),expected_fingerprint:previewToken};const data=await api(`/projects/${encodeURIComponent(project)}/tracks/${encodeURIComponent(track)}/apply`,{method:'POST',body:JSON.stringify(payload)});lastRevision=data.revision_id||'';q('undo').disabled=!lastRevision;notify(data.already_applied?'This exact system is already applied.':'Effect system applied with a revision checkpoint.','good')}catch(e){notify(e.message,'error')}};
q('undo').onclick=async()=>{try{if(!lastRevision)throw new Error('No apply revision is available to restore.');const project=q('project').value.trim();await api(`/projects/${encodeURIComponent(project)}/restore/${encodeURIComponent(lastRevision)}`,{method:'POST'});lastRevision='';q('undo').disabled=true;invalidated();notify('Restored the revision from before the last effect-system apply.','good')}catch(e){notify(e.message,'error')}};
['systemId','systemName','description','version'].forEach(id=>q(id).addEventListener('input',()=>{if(system)invalidated()}));
})();
</script></body></html>"""


def effect_system_creator_page(request: Request):
    member = getattr(request.state, "member", None)
    if member is None:
        raise HTTPException(401, "Membership context unavailable")
    plan = getattr(getattr(member, "plan", None), "id", None)
    if not isinstance(plan, str) or not plan.strip():
        raise HTTPException(401, "Membership plan context unavailable")
    html = _EFFECT_SYSTEM_CREATOR_HTML.replace("__PRODUCT__", escape(PRODUCT_NAME)).replace("__PLAN__", escape(plan))
    return HTMLResponse(
        html,
        headers={
            "Cache-Control": "private, no-store",
            "Pragma": "no-cache",
            "Referrer-Policy": "same-origin",
            "X-Content-Type-Options": "nosniff",
        },
    )


__all__ = ["effect_system_creator_page"]
